:root{--ink:#173c35;--muted:#52675f;--cream:#f7f7ee;--lime:#e3f2ad;--line:#d8dfcf;--accent:#d46540}
html{scroll-behavior:smooth;scroll-padding-top:30px}
body{margin:0;background:var(--cream);color:var(--ink)}
body .demo-root,body .demo-root *{box-sizing:border-box}
body .demo-root{font-family:Arial,Helvetica,sans-serif!important;font-size:16px;line-height:1.55;--container-default-padding:0;padding:0;gap:0;width:100%;max-width:none;color:var(--ink)}
.demo-root .elementor-widget-heading .elementor-heading-title{font-family:Arial,Helvetica,sans-serif;color:inherit}
.demo-root .elementor-widget-heading h1.elementor-heading-title{font-weight:500}
.demo-root .elementor-widget-heading h2.elementor-heading-title{font-weight:500}
.demo-root .elementor-widget-heading h3.elementor-heading-title{font-weight:600}
.demo-root .elementor-widget-text-editor{font-family:Arial,Helvetica,sans-serif;color:inherit}
.demo-root .e-con,.demo-root .elementor-widget{padding:0;margin:0;gap:0;min-width:0;--widgets-spacing:0px;--widgets-spacing-row:0px}
.demo-root .demo-shell{width:min(1160px,calc(100% - 80px));margin-left:auto;margin-right:auto}
.demo-root h1,.demo-root h2,.demo-root h3,.demo-root p{margin:0;color:inherit;font-family:inherit}
.demo-root h1{font-size:clamp(44px,5.6vw,76px);font-weight:500;line-height:1.03;letter-spacing:-3.8px}
.demo-root h2{font-size:clamp(34px,4vw,48px);font-weight:500;line-height:1.12;letter-spacing:-2px}
.demo-root h3{font-size:22px;font-weight:600;line-height:1.25;letter-spacing:-.5px}
.demo-root em{font-family:Georgia,serif;font-weight:400}
.demo-root a{color:inherit;text-decoration:none}
.demo-root a:focus-visible,.demo-root button:focus-visible,.demo-root summary:focus-visible{outline:3px solid var(--accent);outline-offset:5px}
.demo-root .demo-disclosure{background:var(--ink);color:#fff;text-align:center;padding:9px 16px;font-size:10px;letter-spacing:1.5px}
.demo-root .demo-nav{display:flex;flex-direction:row;align-items:center;justify-content:space-between;padding:28px 0;border-bottom:1px solid var(--line)}
.demo-root .brand .elementor-heading-title{font-size:34px;font-weight:700;letter-spacing:-2px}
.brand-dot{color:var(--accent)}
.demo-nav nav{display:flex;gap:35px;align-items:center;font-size:13px}
.demo-nav nav a:last-child{border:1px solid var(--ink);border-radius:30px;padding:9px 18px}
.demo-root .hero{display:grid;grid-template-columns:1.06fr 1fr;gap:40px;align-items:center;padding:86px 0 92px}
.demo-root .hero-copy{display:flex;gap:23px;flex-direction:column}
.demo-root .eyebrow{font-size:10px;font-weight:700;letter-spacing:2px;line-height:1.5}
.demo-root .hero-intro{font-size:17px;color:var(--muted);max-width:450px}
.demo-root .elementor-button{background:var(--ink);color:#fff;border-radius:40px;padding:16px 24px;font-family:inherit;font-size:14px;font-weight:500;border:1px solid var(--ink);transition:background .15s}
.demo-root .elementor-button:hover{background:#285647;color:#fff}
.demo-root .elementor-button-text:after{content:' ↗';margin-left:18px}
.demo-root .quiet-note{font-size:11px;color:var(--muted)}
.studio-art{height:400px;position:relative;display:grid;align-items:center;padding:28px 18px}
.art-orbit{position:absolute;width:320px;height:320px;border-radius:50%;background:var(--lime);top:16px;right:7px}
.art-spark{position:absolute;font-size:89px;color:var(--accent);left:6px;top:-6px;z-index:2;line-height:1}
.art-browser{position:relative;background:#fff;box-shadow:10px 18px 0 #173c3514;border:1px solid #b9c8ba;border-radius:13px;overflow:hidden;transform:rotate(-3deg);width:100%;max-width:430px}
.browser-bar{height:36px;border-bottom:1px solid #dbe4d6;display:flex;align-items:center;gap:5px;padding:0 14px;background:#fbfcf6}
.browser-bar i{width:5px;height:5px;border-radius:50%;background:#a9b6a7}
.browser-bar span{font-size:8px;margin-left:10px;color:var(--muted)}
.browser-inner{padding:25px 26px 20px}
.art-pill{font-size:7px;letter-spacing:1px;padding:5px 7px;border-radius:20px;background:var(--lime)}
.art-title{font-size:29px;line-height:1.1;letter-spacing:-1px;margin:17px 0}
.art-line{height:5px;width:78%;background:#e2e7dc;margin:8px 0;border-radius:5px}
.art-line.short{width:56%}
.art-button{display:inline-block;font-size:7px;letter-spacing:.5px;padding:10px 14px;background:var(--ink);color:#fff;border-radius:20px;margin-top:10px}
.art-tiles{display:flex;gap:12px;margin-top:22px}.art-tiles b{height:39px;flex:1;background:#eef2e7;border-radius:5px}.art-tiles b:nth-child(2){background:#f7e3d7}
.art-note{position:absolute;bottom:8px;right:0;background:#fff;padding:14px 19px;border:1px solid #d5ddce;border-radius:10px;font-size:11px;box-shadow:0 8px 22px #173c3510;transform:rotate(3deg)}
.art-note span{display:inline-grid;place-items:center;width:25px;height:25px;background:var(--lime);border-radius:50%;margin-right:6px}
.demo-root .service-section{padding:48px 0 85px;border-top:1px solid var(--line)}
.demo-root .section-heading{gap:17px;max-width:650px}.section-heading>div:last-child{color:var(--muted)}
.demo-root .service-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px;margin-top:36px}
.demo-root .service-card{border:1px solid var(--line);border-radius:15px;display:flex;flex-direction:column;gap:18px;padding:28px;min-height:280px;background:#fbfcf5}
.demo-root .service-card:nth-child(2){background:var(--lime);border-color:var(--lime)}
.service-card .card-number{font-size:11px;color:var(--muted);margin-bottom:10px}
.service-card>.elementor-widget-text-editor:not(.card-number):not(.card-label){color:var(--muted);font-size:14px}
.service-card .card-label{font-size:9px;letter-spacing:1px;font-weight:700;margin-top:auto;padding-top:10px}
.demo-root .process-section{background:var(--ink);color:#f7f7ee;padding:68px 0}
.demo-root .process-inner{display:grid;grid-template-columns:1fr 1.2fr;gap:90px}
.demo-root .process-title{gap:20px}.process-title .eyebrow{color:var(--lime)}.process-title>div:last-child{font-size:14px;color:#d2dfd3;max-width:290px}
.demo-root .process-steps{display:flex;gap:25px;flex-direction:column}
.demo-root .process-step{display:grid;grid-template-columns:35px 1fr;gap:20px;border-bottom:1px solid #ffffff29;padding-bottom:25px}
.demo-root .process-step:last-child{border:0;padding-bottom:0}.step-number{font-size:12px;color:var(--lime)}.demo-root .step-copy{gap:9px}.step-copy h3{font-size:19px}.step-copy p{font-size:13px;color:#d2dfd3}
.demo-root .contact-section{display:grid;grid-template-columns:1fr 1.1fr;gap:80px;padding:88px 0}
.demo-root .contact-copy{gap:21px}.contact-copy>div:nth-child(3){color:var(--muted);max-width:360px;font-size:15px}
.mini-faq{margin-top:16px;max-width:370px}.mini-faq details{border-bottom:1px solid var(--line);padding:16px 0}.mini-faq summary{cursor:pointer;font-size:13px;font-weight:600}.mini-faq details p{font-size:12px;color:var(--muted);padding-top:12px}
.demo-root .contact-form-card{background:#fff;border:1px solid var(--line);border-radius:18px;padding:28px}
.demo-form label{display:block;font-size:12px;font-weight:600;margin:0 0 18px;color:var(--ink)}
.field-row{display:grid;grid-template-columns:1fr 1fr;gap:16px}
.demo-form input,.demo-form select,.demo-form textarea{display:block;width:100%;min-height:44px;margin:7px 0 0;border:1px solid #b9c7bc;border-radius:7px;background:#fcfdf9;font:13px Arial,sans-serif;padding:12px;color:var(--ink)}
.demo-form input:focus,.demo-form select:focus,.demo-form textarea:focus{outline:2px solid var(--ink);outline-offset:2px}
.demo-form textarea{resize:vertical;min-height:105px}.demo-root .demo-notice{font-size:11px;color:var(--muted);margin:0 0 18px}
.demo-form button{width:100%;padding:15px 20px;border:0;border-radius:30px;background:var(--ink);color:#fff;font:14px Arial,sans-serif;cursor:pointer;display:flex;justify-content:space-between}
.demo-root #form-result{font-size:13px;margin-top:16px;border-left:3px solid var(--ink);padding:10px;background:var(--lime)}
.demo-root .demo-footer{display:flex;flex-direction:row;justify-content:space-between;align-items:center;padding:26px 0 34px;border-top:1px solid var(--line)}
.demo-footer p{font-size:10px;color:var(--muted);text-align:right;line-height:1.8}
@media(max-width:900px){.demo-root .demo-shell{width:calc(100% - 48px)}.demo-root .hero{gap:20px;padding:55px 0}.studio-art{height:330px;padding:24px 8px}.art-title{font-size:24px}.art-orbit{width:250px;height:250px}.demo-root .process-inner,.demo-root .contact-section{gap:35px}.demo-root .service-card{padding:22px}.demo-root h1{letter-spacing:-2.7px}}
@media(max-width:640px){.demo-root .demo-shell{width:calc(100% - 40px)}.demo-root .demo-nav{padding:20px 0}.demo-nav nav{gap:15px;font-size:11px}.demo-nav nav a:last-child{padding:7px 10px}.demo-nav nav a:nth-child(2){display:none}.demo-root .hero{grid-template-columns:1fr;padding:43px 0 45px;gap:25px}.demo-root h1{font-size:49px;letter-spacing:-2.9px}.demo-root h2{font-size:36px;letter-spacing:-1.7px}.demo-root .hero-copy{gap:19px}.demo-root .hero-intro{font-size:16px}.studio-art{height:340px;max-width:440px;margin:auto;width:100%;padding:30px 9px}.art-browser{max-width:none}.art-orbit{width:275px;height:275px}.art-spark{font-size:65px}.art-note{right:3px;bottom:4px}.demo-root .service-section{padding:35px 0 50px}.demo-root .service-grid{grid-template-columns:1fr;gap:13px;margin-top:25px}.demo-root .service-card{min-height:240px;gap:15px;padding:25px}.service-card .card-number{margin-bottom:3px}.demo-root .process-section{padding:45px 0}.demo-root .process-inner,.demo-root .contact-section{grid-template-columns:1fr;gap:32px}.demo-root .contact-section{padding:50px 0}.demo-root .contact-form-card{padding:23px 19px}.field-row{grid-template-columns:1fr;gap:0}.demo-root .demo-footer{align-items:flex-start;gap:20px}.demo-footer p{max-width:225px;font-size:9px}.demo-root .demo-disclosure{font-size:8px;letter-spacing:1.1px}}
.demo-form .demo-honeypot{position:absolute;left:-10000px;width:1px;height:1px;overflow:hidden}
.demo-form button:disabled{opacity:.65;cursor:wait}
.demo-root #form-result[data-state="error"]{background:#fff0e9;border-left-color:#9c3522;color:#7f2518}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}.demo-root .elementor-button{transition:none}}

document.addEventListener('DOMContentLoaded', () => {
  const form = document.querySelector('#project-form');
  if (!form) return;
  const result = document.querySelector('#form-result');
  const submit = form.querySelector('button[type="submit"]');
  const label = submit.innerHTML;
  let pending = false;
  const showResult = (message, failed = false) => {
    result.textContent = message;
    result.dataset.state = failed ? 'error' : 'success';
    result.hidden = false;
    result.focus();
  };
  form.addEventListener('submit', async event => {
    event.preventDefault();
    if (pending) return;
    const name = form.elements.namedItem('name');
    const message = form.elements.namedItem('message');
    name.setCustomValidity(name.value.trim().length >= 2 ? '' : 'Please enter at least two characters.');
    message.setCustomValidity(message.value.trim().length >= 10 ? '' : 'Please add at least 10 meaningful characters.');
    if (!form.reportValidity()) return;
    if (!window.LumaDemo?.enabled) {
      showResult('The local preview is not enabled. Start the supplied demo runtime.', true);
      return;
    }
    pending = true;
    submit.disabled = true;
    form.setAttribute('aria-busy', 'true');
    submit.textContent = 'Checking your enquiry…';
    result.hidden = true;
    try {
      const response = await fetch(window.LumaDemo.endpoint, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'X-WP-Nonce': window.LumaDemo.nonce },
        credentials: 'same-origin',
        body: JSON.stringify(Object.fromEntries(new FormData(form))),
      });
      const payload = await response.json();
      if (!response.ok) {
        const errors = payload.data?.fields || {};
        for (const [key, error] of Object.entries(errors)) {
          const control = form.elements.namedItem(key);
          if (control && 'setCustomValidity' in control) control.setCustomValidity(error);
        }
        showResult(payload.message || 'The preview could not be checked. Please try again.', true);
        return;
      }
      showResult(`Checked by WordPress, ${payload.enquiry.name}. Your enquiry is valid. Demo only: no email was sent and nothing was saved.`);
    } catch {
      showResult('The local server could not be reached. Your text is still here; try again when it is available.', true);
    } finally {
      pending = false;
      submit.disabled = false;
      submit.innerHTML = label;
      form.removeAttribute('aria-busy');
    }
  });
  form.addEventListener('input', event => {
    if ('setCustomValidity' in event.target) event.target.setCustomValidity('');
    result.hidden = true;
  });
});
